options(digits = 17)
values <- c(1, 2, 4, 8)
w <- matrix(c(0,1,0,0, 1,0,1,0, 0,1,0,1, 0,0,1,0), nrow=4, byrow=TRUE)
centered <- values - mean(values)
s0 <- sum(w)
moran <- length(values) / s0 * as.numeric(t(centered) %*% w %*% centered) / sum(centered^2)
geary <- (length(values)-1) / (2*s0) * sum(w * (outer(values, values, "-")^2)) / sum(centered^2)
getis <- sum(w * outer(values, values)) / (sum(values)^2 - sum(values^2))
cat(sprintf("moran,%.17g\n", moran))
cat(sprintf("geary,%.17g\n", geary))
cat(sprintf("getis,%.17g\n", getis))
